from httpbin.core import app
client = app.test_client()

def test_weighted_comma_list_only_returns_listed_codes():
    allowed = {200, 500}
    for _ in range(40):
        r = client.get('/status/200:3,500:1', follow_redirects=False)
        assert r.status_code in allowed, f"Unexpected status: {r.status_code}"

test_weighted_comma_list_only_returns_listed_codes()

from httpbin.core import app
client = app.test_client()

def test_comma_list_does_not_return_unlisted_code():
    forbidden = {500, 301, 302, 418}
    for _ in range(50):
        r = client.get('/status/200,404', follow_redirects=False)
        assert r.status_code not in forbidden, f"Forbidden status returned: {r.status_code}"
        assert r.status_code in {200, 404}, f"Unexpected status: {r.status_code}"

test_comma_list_does_not_return_unlisted_code()
